package ru.truetv.bridge;
import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import javax.net.SocketFactory;
/** Regression: protocol completion frees the next transfer even if TCP/TLS shutdown stalls. */
public final class RepeatTransferCheck {
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("repeat236-").toFile();Identity tv=Identity.load(new File(root,"tv")),phone=Identity.load(new File(root,"phone"));BlockingQueue<Boolean> finished=new LinkedBlockingQueue<>();List<byte[]> received=Collections.synchronizedList(new ArrayList<>());Transfer.Receiver r=new Transfer.Receiver(tv,"TV",item->new Wire.Target(){ByteArrayOutputStream data=new ByteArrayOutputStream();public OutputStream stream(){return data;}public String publish(){received.add(data.toByteArray());return item.name;}public void discard(){}},(o,f,c)->true,new Transfer.Events(){public void update(int i,String n,long b,long t){}public void finished(boolean s,String d){finished.add(s);}});Thread accept=new Thread(()->{try{r.accept();}catch(IOException expected){}});accept.start();CountDownLatch closing=new CountDownLatch(1),release=new CountDownLatch(1);SocketFactory slowClose=new SocketFactory(){public Socket createSocket(){return new Socket(){public void close()throws IOException{closing.countDown();try{release.await(15,TimeUnit.SECONDS);}catch(InterruptedException ignored){}super.close();}};}public Socket createSocket(String h,int p)throws IOException{throw new IOException();}public Socket createSocket(String h,int p,InetAddress l,int q)throws IOException{throw new IOException();}public Socket createSocket(InetAddress h,int p)throws IOException{throw new IOException();}public Socket createSocket(InetAddress h,int p,InetAddress l,int q)throws IOException{throw new IOException();}};
 try{for(int i=0;i<12;i++){byte[] payload=("payload-"+i).getBytes("UTF-8");long start=System.nanoTime();new Transfer.Sender().send(phone,InetAddress.getLoopbackAddress(),r.port(),tv.fingerprint(),new Wire.Offer("Phone",Collections.singletonList(new Wire.Item("file-"+i,"application/octet-stream",payload.length))),n->new ByteArrayInputStream(payload),BridgeCheck.quiet,i==0?slowClose:SocketFactory.getDefault());if(i==0){if(System.nanoTime()-start>TimeUnit.SECONDS.toNanos(5)||!closing.await(5,TimeUnit.SECONDS))throw new AssertionError("completion blocked by socket close");}if(!Boolean.TRUE.equals(finished.poll(5,TimeUnit.SECONDS)))throw new AssertionError("receiver did not finish "+i);if(!Arrays.equals(payload,received.get(i)))throw new AssertionError("stale payload "+i);}System.out.println("PASS 12 consecutive transfers, exact distinct payloads; stalled close cannot block sender completion or the next receiver request");}finally{release.countDown();r.close();accept.join(3000);}}
}
